WITH order_items_by_product AS (SELECT product_id, MAX(unit_price) - MIN(unit_price) unit_price_range FROM order_items GROUP BY product_id) SELECT p.id, p.stock_qty, p.supplier_id, oibp.unit_price_range FROM products p JOIN order_items_by_product oibp ON p.id = oibp.product_id ORDER BY supplier_id DESC;
